'use strict';

// MODULES //

var tape = require( 'tape' );
var Float32Array = require( '@stdlib/array/float32' );
var sfirstIndexNotEqual = require( './../lib/ndarray.js' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof sfirstIndexNotEqual, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 7', function test( t ) {
	t.strictEqual( sfirstIndexNotEqual.length, 7, 'has expected arity' );
	t.end();
});

tape( 'the function returns the first index of an element which is not equal to a corresponding element in another array', function test( t ) {
	var actual;
	var x;
	var y;

	x = new Float32Array( [ 1.0, 1.0, 2.0, 2.0, 3.0, 3.0 ] );
	y = new Float32Array( [ 1.0, 1.0, 2.0, 5.0, 3.0, 3.0 ] );

	actual = sfirstIndexNotEqual( x.length, x, 1, 0, y, 1, 0 );
	t.strictEqual( actual, 3, 'returns expected value' );

	t.end();
});

tape( 'the function returns `-1` if unable to find an element which is not equal to a corresponding element in another array', function test( t ) {
	var actual;
	var x;
	var y;

	x = new Float32Array( [ 1.0, 2.0, 3.0 ] );
	y = new Float32Array( [ 1.0, 2.0, 3.0 ] );

	actual = sfirstIndexNotEqual( x.length, x, 1, 0, y, 1, 0 );
	t.strictEqual( actual, -1, 'returns expected value' );

	t.end();
});

tape( 'the function returns `-1` if a provided `N` parameter is less than or equal to zero', function test( t ) {
	var actual;
	var x;
	var y;

	x = new Float32Array( [ 1.0, 2.0, 3.0 ] );
	y = new Float32Array( [ 1.0, 2.0, 3.0 ] );

	actual = sfirstIndexNotEqual( 0, x, 1, 0, y, 1, 0 );
	t.strictEqual( actual, -1, 'returns expected value' );

	actual = sfirstIndexNotEqual( -1, x, 1, 0, y, 1, 0 );
	t.strictEqual( actual, -1, 'returns expected value' );

	t.end();
});

tape( 'the function treats corresponding `NaN` elements as unequal', function test( t ) {
	var actual;

	actual = sfirstIndexNotEqual( 1, new Float32Array( [ NaN ] ), 1, 0, new Float32Array( [ NaN ] ), 1, 0 );
	t.strictEqual( actual, 0, 'returns expected value' );

	t.end();
});

tape( 'the function treats `-0` and `+0` as equal', function test( t ) {
	var actual;

	actual = sfirstIndexNotEqual( 1, new Float32Array( [ -0.0 ] ), 1, 0, new Float32Array( [ 0.0 ] ), 1, 0 );
	t.strictEqual( actual, -1, 'returns expected value' );

	t.end();
});

tape( 'the function supports an `x` stride', function test( t ) {
	var actual;
	var x;
	var y;

	x = new Float32Array([
		0.0, // 0
		9.0,
		0.0, // 1
		9.0,
		1.0  // 2
	]);
	y = new Float32Array([
		0.0, // 0
		0.0, // 1
		0.0  // 2
	]);

	actual = sfirstIndexNotEqual( 3, x, 2, 0, y, 1, 0 );
	t.strictEqual( actual, 2, 'returns expected value' );

	t.end();
});

tape( 'the function supports a `y` stride', function test( t ) {
	var actual;
	var x;
	var y;

	x = new Float32Array([ 0.0, 0.0, 1.0 ]);
	y = new Float32Array([
		0.0, // 0
		9.0,
		0.0, // 1
		9.0,
		0.0  // 2
	]);

	actual = sfirstIndexNotEqual( 3, x, 1, 0, y, 2, 0 );
	t.strictEqual( actual, 2, 'returns expected value' );

	t.end();
});

tape( 'the function supports negative strides', function test( t ) {
	var actual;
	var x;
	var y;

	x = new Float32Array( [ 5.0, 4.0, 3.0, 2.0, 1.0, 0.0 ] );
	y = new Float32Array( [ 5.0, 4.0, 3.0, 9.0, 1.0, 0.0 ] );

	actual = sfirstIndexNotEqual( x.length, x, -1, x.length-1, y, -1, y.length-1 ); // eslint-disable-line max-len
	t.strictEqual( actual, 2, 'returns expected value' );

	t.end();
});

tape( 'the function supports an `x` offset', function test( t ) {
	var actual;
	var x;
	var y;

	x = new Float32Array([
		9.0,
		0.0, // 0
		9.0,
		0.0, // 1
		9.0,
		1.0  // 2
	]);
	y = new Float32Array([
		0.0, // 0
		0.0, // 1
		0.0  // 2
	]);

	actual = sfirstIndexNotEqual( 3, x, 2, 1, y, 1, 0 );
	t.strictEqual( actual, 2, 'returns expected value' );

	t.end();
});

tape( 'the function supports a `y` offset', function test( t ) {
	var actual;
	var x;
	var y;

	x = new Float32Array([ 0.0, 0.0, 1.0 ]);
	y = new Float32Array([
		9.0,
		0.0, // 0
		9.0,
		0.0, // 1
		9.0,
		0.0  // 2
	]);

	actual = sfirstIndexNotEqual( 3, x, 1, 0, y, 2, 1 );
	t.strictEqual( actual, 2, 'returns expected value' );

	t.end();
});

tape( 'the function supports complex access patterns', function test( t ) {
	var actual;
	var x;
	var y;

	x = new Float32Array([
		0.0, // 0
		9.0,
		0.0, // 1
		9.0,
		1.0  // 2
	]);
	y = new Float32Array([
		0.0,  // 2
		0.0,  // 1
		0.0,  // 0
		9.0,
		9.0
	]);

	actual = sfirstIndexNotEqual( 3, x, 2, 0, y, -1, 2 );
	t.strictEqual( actual, 2, 'returns expected value' );

	t.end();
});
